CREATE TYPE public.app_role AS ENUM ('customer','creator');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', active_context text NOT NULL DEFAULT 'customer' CHECK (active_context IN ('customer','creator')), preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.creator_profiles (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, slug text NOT NULL UNIQUE, display_name text NOT NULL, disciplines text[] NOT NULL DEFAULT '{}', city text NOT NULL DEFAULT '', country text NOT NULL DEFAULT 'Zambia', bio text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', cover_url text NOT NULL DEFAULT '', capabilities jsonb NOT NULL DEFAULT '{"portfolio":true,"sellsWorks":false,"acceptsCommissions":false,"offersServices":false,"acceptsBookings":false}', portfolio jsonb NOT NULL DEFAULT '[]', published boolean NOT NULL DEFAULT false);
GRANT SELECT, UPDATE ON public.creator_profiles TO authenticated; GRANT SELECT ON public.creator_profiles TO anon; GRANT ALL ON public.creator_profiles TO service_role;
ALTER TABLE public.creator_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_creator_read ON public.creator_profiles FOR SELECT TO anon,authenticated USING (published);
CREATE POLICY own_creator_read ON public.creator_profiles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY own_creator_update ON public.creator_profiles FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.profiles(id), creator_id uuid NOT NULL REFERENCES public.profiles(id), source text NOT NULL CHECK(source IN ('commission','service','booking','custom-quote')), title text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','discussing','awaiting-payment','confirmed','in-progress','awaiting-review','completed','cancelled')), price numeric, currency text NOT NULL DEFAULT 'ZMW', milestones jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_participants_read ON public.projects FOR SELECT TO authenticated USING(customer_id=auth.uid() OR creator_id=auth.uid());
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.profiles(id), creator_id uuid NOT NULL REFERENCES public.profiles(id), context_type text NOT NULL CHECK(context_type IN ('work-enquiry','project','service')), context_id text NOT NULL, context_title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_participants_read ON public.conversations FOR SELECT TO authenticated USING(customer_id=auth.uid() OR creator_id=auth.uid());
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_message_read ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND (c.customer_id=auth.uid() OR c.creator_id=auth.uid())));
CREATE POLICY participant_message_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND (c.customer_id=auth.uid() OR c.creator_id=auth.uid())));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), context text NOT NULL CHECK(context IN ('creator','customer','global')), title text NOT NULL, body text NOT NULL DEFAULT '', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE(read_at) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_notification_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_notification_mark ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.saved_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('work','artist','service','collection')), item_slug text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,kind,item_slug));
GRANT SELECT, INSERT, DELETE ON public.saved_items TO authenticated; GRANT ALL ON public.saved_items TO service_role;
ALTER TABLE public.saved_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_saved_read ON public.saved_items FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_saved_insert ON public.saved_items FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY own_saved_delete ON public.saved_items FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.profiles(id), work_slug text NOT NULL, artist_slug text NOT NULL, title text NOT NULL, image_url text NOT NULL DEFAULT '', amount numeric NOT NULL, currency text NOT NULL DEFAULT 'ZMW', delivery text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'payment-pending' CHECK(status IN ('payment-pending','confirmed','preparing','ready-for-collection','in-transit','delivered','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_order_read ON public.orders FOR SELECT TO authenticated USING(customer_id=auth.uid());
CREATE TABLE public.collection_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), order_id uuid NOT NULL REFERENCES public.orders(id), work_slug text NOT NULL, acquired_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id));
GRANT SELECT ON public.collection_items TO authenticated; GRANT ALL ON public.collection_items TO service_role;
ALTER TABLE public.collection_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_collection_read ON public.collection_items FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'customer'); RETURN new; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE FUNCTION public.publish_creator(_name text,_disciplines text[],_city text,_country text,_bio text,_avatar text,_cover text,_capabilities jsonb,_portfolio jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); profile_slug text; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(_name))<1 OR length(_name)>120 OR length(_bio)>10000 OR cardinality(_disciplines)<1 THEN RAISE EXCEPTION 'Invalid creative profile'; END IF; profile_slug:=regexp_replace(lower(trim(_name)),'[^a-z0-9]+','-','g')||'-'||substr(uid::text,1,8); INSERT INTO public.creator_profiles(user_id,slug,display_name,disciplines,city,country,bio,avatar_url,cover_url,capabilities,portfolio,published) VALUES(uid,profile_slug,_name,_disciplines,_city,_country,_bio,_avatar,_cover,_capabilities,_portfolio,true) ON CONFLICT(user_id) DO UPDATE SET display_name=EXCLUDED.display_name,disciplines=EXCLUDED.disciplines,city=EXCLUDED.city,country=EXCLUDED.country,bio=EXCLUDED.bio,avatar_url=EXCLUDED.avatar_url,cover_url=EXCLUDED.cover_url,capabilities=EXCLUDED.capabilities,portfolio=EXCLUDED.portfolio,published=true RETURNING slug INTO profile_slug; INSERT INTO public.user_roles(user_id,role) VALUES(uid,'creator') ON CONFLICT(user_id,role) DO NOTHING; UPDATE public.profiles SET display_name=_name,active_context='creator' WHERE id=uid; RETURN profile_slug; END; $$;
REVOKE ALL ON FUNCTION public.publish_creator(text,text[],text,text,text,text,text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.publish_creator(text,text[],text,text,text,text,text,jsonb,jsonb) TO authenticated;
CREATE INDEX projects_customer_idx ON public.projects(customer_id); CREATE INDEX projects_creator_idx ON public.projects(creator_id); CREATE INDEX conversations_customer_idx ON public.conversations(customer_id); CREATE INDEX conversations_creator_idx ON public.conversations(creator_id); CREATE INDEX messages_conversation_idx ON public.messages(conversation_id); CREATE INDEX notifications_user_idx ON public.notifications(user_id); CREATE INDEX orders_customer_idx ON public.orders(customer_id);